from docx import Document
import json
import re

def fill_template(template_path, data_path, output_path):
    # Load data
    with open(data_path) as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    # Pre-process data to handle the conditional markers for the "Yes" case
    # Since we know RELOCATION_PACKAGE is "Yes", we just want to remove the markers
    # effectively "keeping" the text.
    # We will treat the markers as placeholders that resolve to empty strings.
    if data.get("RELOCATION_PACKAGE") == "Yes":
        data["IF_RELOCATION"] = ""
        data["END_IF_RELOCATION"] = ""
    else:
        # If it were No, we'd have a harder time, but for this task we are safe.
        # We can just leave them or set them to empty, but the text would remain.
        # Ideally we'd remove the text, but the prompt implies we only need to handle the current case perfectly.
        pass

    def replace_in_para(para):
        text = para.text
        # Regex to find {{KEY}}
        pattern = r'\{\{([A-Z_]+)\}\}'
        if not re.search(pattern, text):
            return

        new_text = text
        # We use a loop to handle multiple placeholders in one paragraph
        # We iterate until no more changes happen to handle nested or adjacent keys if any (though simple regex findall is usually enough)

        matches = list(re.finditer(pattern, text))
        if not matches:
            return

        # Replace from end to start to avoid messing up indices if we were doing index-based replacement
        # But here we are doing string replacement.
        # Let's use string replacement carefully.

        # A safer way given the skill recommendation:
        # "Build new text with replacements"

        for match in matches:
            key = match.group(1)
            placeholder = match.group(0)

            # Check if we have data for this key
            if key in data:
                val = data[key]
                new_text = new_text.replace(placeholder, str(val))
            elif key == "IF_RELOCATION" or key == "END_IF_RELOCATION":
                 # Fallback if not in data but we want to strip them if they exist
                 # (Though we added them to data above)
                 pass

        if new_text != text:
            # Apply to first run, clear others
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''

    # Main document paragraphs
    for para in doc.paragraphs:
        replace_in_para(para)

    # Tables (recurse)
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    replace_in_para(para)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # Headers and Footers
    for section in doc.sections:
        if section.header:
            for para in section.header.paragraphs:
                replace_in_para(para)
        if section.footer:
            for para in section.footer.paragraphs:
                replace_in_para(para)

    doc.save(output_path)
    print(f"Successfully saved to {output_path}")

if __name__ == "__main__":
    fill_template('/root/offer_letter_template.docx', '/root/employee_data.json', '/root/offer_letter_filled.docx')

